    test "every builder returns its pinned classes from the engine's helpers alone" do
      view = ActionView::Base.empty.extend(Lostcoords::Ui::Engine.helpers)

      SNAPSHOT.each do |call, expected|
        assert_equal expected, view.instance_eval(call), call
      end
